CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS about (id integer PRIMARY KEY DEFAULT 1, name text NOT NULL, title text NOT NULL, bio text NOT NULL, profile_image text, location text, email text, phone text, github_url text, linkedin_url text, other_socials jsonb NOT NULL DEFAULT '[]'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS skills (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, category text NOT NULL, proficiency integer NOT NULL CHECK(proficiency BETWEEN 0 AND 100), icon text, display_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS experience (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_title text NOT NULL, company text NOT NULL, location text, start_date date, end_date date, current boolean NOT NULL DEFAULT false, description text, achievements jsonb NOT NULL DEFAULT '[]'::jsonb, display_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS education (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), institution text NOT NULL, degree text NOT NULL, field text, start_date date, end_date date, grade text, description text, display_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS certifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, issuer text NOT NULL, issue_date date, credential_id text, credential_url text, description text, icon text, display_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, description text NOT NULL, icon text, display_order integer NOT NULL DEFAULT 0, published boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, slug text UNIQUE NOT NULL, short_description text NOT NULL, case_study text, image_url text, technologies jsonb NOT NULL DEFAULT '[]'::jsonb, github_url text, live_demo_url text, status text NOT NULL DEFAULT 'Completed' CHECK(status IN ('Completed','In Progress','Archived')), featured boolean NOT NULL DEFAULT false, published boolean NOT NULL DEFAULT true, display_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS resume (id integer PRIMARY KEY DEFAULT 1, file_url text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL, subject text NOT NULL, message text NOT NULL, is_read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS projects_order_idx ON projects(display_order, created_at DESC);
CREATE INDEX IF NOT EXISTS messages_read_idx ON messages(is_read, created_at DESC);
